import numpy as np
from scipy.optimize import least_squares
d=meas['m3']; x=d['two_theta']; y=np.array(d['counts'],float)
def pv(x,x0,w,eta=0.5):
    g=np.exp(-4*np.log(2)*((x-x0)/w)**2)
    l=1/(1+4*((x-x0)/w)**2)
    return eta*l+(1-eta)*g
def cub(p):
    x0,w,A,b0,b1=p
    return A*pv(x,x0,w)+b0+b1*(x-45)
def tet(p):
    x0,w,A,b0,b1,ca=p  # ca: splitting in deg
    return A*(pv(x,x0,w)*(2/3)+pv(x,x0-ca,w)*(1/3))+b0+b1*(x-45)
def tetc(p):
    x0,w,A,b0,b1,ca=p
    return A*(pv(x,x0,w)*(2/3)+pv(x,x0-ca,w)*(1/3))+b0+b1*(x-45)
best=None
for x0 in np.linspace(45.15,45.32,8):
    r=least_squares(lambda p: (cub(p)-y)/np.sqrt(np.maximum(y,1)), [x0,0.15,60,60,0])
    if best is None or r.cost<best.cost: best=r
c=2*best.cost
print('cubic chi2',round(c,1),best.x.round(4))
bt=None
for ca in [0.06,0.08,0.10,0.12,0.14,0.16]:
  for x0 in np.linspace(45.2,45.35,4):
    r=least_squares(lambda p: (tet(list(p)+[ca] if False else p)-y)/np.sqrt(np.maximum(y,1)) if False else (tet(list(p)+[ca])-y)/np.sqrt(np.maximum(y,1)), [x0,0.12,60,60,0])
    if bt is None or r.cost<bt[0].cost: bt=(r,ca)
print('doublet chi2',round(2*bt[0].cost,1),bt[0].x.round(4),'split',bt[1])
# free split
def tetf(p):
    return tet(p)
bf=None
for ca in [0.02,0.05,0.08,0.1,0.12,0.14]:
    r=least_squares(lambda p: (tet(list(p[:5])+[p[5]])-y)/np.sqrt(np.maximum(y,1)), [45.25,0.12,60,60,0,ca])
    if bf is None or r.cost<bf.cost: bf=r
print('doublet free split chi2',round(2*bf.cost,1),bf.x.round(4))

