import numpy as np
from scipy.optimize import least_squares
x=meas['m3']['two_theta']; y=np.array(meas['m3']['counts'],float)+np.array(meas['m4']['counts'],float)
def pv(x,x0,w,eta=0.5):
    g=np.exp(-4*np.log(2)*((x-x0)/w)**2); l=1/(1+4*((x-x0)/w)**2)
    return eta*l+(1-eta)*g
def cub(p):
    x0,w,A,b0,b1=p
    return A*pv(x,x0,w)+b0+b1*(x-45)
def tet(p):
    x0,w,A,b0,b1,s=p
    return A*(pv(x,x0,w)*(2/3)+pv(x,x0-s,w)*(1/3))+b0+b1*(x-45)
# counts doubled -> sum of two scans: model expected = 2x single
def chi(m): return (m-y)/np.sqrt(np.maximum(y,1))
bc=None
for x0 in np.linspace(45.15,45.32,8):
    for w0 in [0.12,0.18]:
        r=least_squares(lambda p: chi(cub(p)), [x0,w0,120,130,-5])
        if bc is None or r.cost<bc.cost: bc=r
bt=None
for s0 in [0.06,0.1,0.13,0.16]:
    for x0 in [45.25,45.3]:
        r=least_squares(lambda p: chi(tet(p)), [x0,0.12,120,130,-5,s0])
        if bt is None or r.cost<bt.cost: bt=r
print('cubic chi2',round(2*bc.cost,1),bc.x.round(4))
print('doublet chi2',round(2*bt.cost,1),bt.x.round(4))
print('dchi2',round(2*(bc.cost-bt.cost),1))
# scan split for profile
for s in [0.0,0.04,0.08,0.10,0.12,0.14,0.16]:
    rr=None
    for x0 in [45.25,45.3]:
        r=least_squares(lambda p: chi(tet(list(p)+[s])), [x0,0.12,120,130,-5])
        if rr is None or r.cost<rr.cost: rr=r
    print('split',s,'chi2',round(2*rr.cost,1))

